// NavNet → n8n: check the event is really from NavNet, and prepare the messages.
// Paste the same secret as N8N_WEBHOOK_SECRET in NavNet's server/.env (leave '' to skip the check;
// the check needs NODE_FUNCTION_ALLOW_BUILTIN=crypto on your n8n).
const SECRET = '';

const out = [];
for (const item of $input.all()) {
  const req = item.json;
  const e = req.body || {};
  if (SECRET) {
    const crypto = require('crypto');
    const expected = 'sha256=' + crypto.createHmac('sha256', SECRET).update(JSON.stringify(e)).digest('hex');
    if ((req.headers || {})['x-navnet-signature'] !== expected) throw new Error('Signature mismatch: this request did not come from NavNet');
  }
  const rider = e.rider || {};
  const card = rider.emergencyCard || {};
  const captain = e.captain || {};
  const a = e.alert || {};
  const trip = e.trip || {};
  let kind = 'other';
  if (e.event === 'alert.raised' && a.emergency) kind = 'emergency';
  else if (e.event === 'trip.ended') kind = 'trip_ended';

  const title = a.type === 'SOS' ? 'SOS' : a.type === 'POSSIBLE_CRASH' ? 'Possible crash' : (a.type || '').replace(/_/g, ' ');
  const emergencyText = [
    `🚨 NavNet ${title}: ${rider.name || 'A rider'} may need help.`,
    a.message,
    a.mapLink ? `Location: ${a.mapLink}` : null,
    `Trip: ${trip.name || ''}`,
    captain.name ? `Ride captain: ${captain.name}${captain.phone ? ' (' + captain.phone + ')' : ''}` : null,
    card.bloodGroup ? `Blood group: ${card.bloodGroup}` : null,
  ].filter(Boolean).join('\n');

  const s = e.summary || {};
  const summaryText = `🏁 ${trip.name || 'Trip'} finished: ${s.distanceKm ?? '?'} km in ${s.durationMinutes ?? '?'} min, ` +
    `avg ${s.averageSpeedKmh ?? '?'} km/h, ${s.ridersArrived ?? 0}/${s.riders ?? 0} riders arrived, ${s.sosCount ?? 0} SOS.`;

  out.push({ json: {
    kind,
    event: e.event,
    alertType: a.type || null,
    riderName: rider.name || null,
    emergencyContactPhone: card.contactPhone || null,
    // No emergency contact on the card? The WhatsApp goes to the captain instead.
    whatsappTo: card.contactPhone || captain.phone || null,
    captainPhone: captain.phone || null,
    emergencyText,
    summaryText,
    sheetRow: {
      Date: (e.sentAt || '').slice(0, 10),
      Trip: trip.name || '',
      'Distance (km)': s.distanceKm ?? '',
      'Duration (min)': s.durationMinutes ?? '',
      'Avg speed (km/h)': s.averageSpeedKmh ?? '',
      'Max speed (km/h)': s.maxSpeedKmh ?? '',
      'Riders arrived': `${s.ridersArrived ?? 0}/${s.riders ?? 0}`,
      SOS: s.sosCount ?? 0,
    },
  } });
}
return out;
